class TaskInputRejected(AccessError):
    """Confirmed upstream validation rejection before task creation."""
    def __init__(self, log_id=None):
        super().__init__('Browser Tool rejected the task input (HTTP 422); no task was created. '
                         'The existing browser session remains available.', 422)
        self.log_id = log_id if isinstance(log_id, str) and log_id.startswith('log_') else None


class TaskSessionExpired(AccessError):
    """Confirmed rejection of a stopped browser before task creation."""
    def __init__(self, log_id=None):
        super().__init__('Browser Tool rejected the stopped browser; no task was created. '
                         'Start the requested task again to open a fresh browser.', 410)
        self.log_id = log_id if isinstance(log_id, str) and log_id.startswith('log_') else None


def task_session_expired(result):
    data = result.get('data')
    if not isinstance(data, dict) or data.get('status_code') != 400:
        return False
    if any(data.get(k) for k in ('id', 'task_id', 'taskId', 'watch_task_id', 'browser_session_id')):
        return False
    try:
        return json.loads(data.get('message', '')).get('detail') == (
            'Browser session is stopped. Please start a new session and try again.')
    except (ValueError, TypeError, AttributeError):
        return False


def task_input_rejected(result):
    data = result.get('data')
    if not isinstance(data, dict) or data.get('status_code') != 422:
        return False
    if any(data.get(k) for k in ('id', 'task_id', 'taskId', 'watch_task_id', 'browser_session_id')):
        return False
    try:
        detail = json.loads(data.get('message', ''))['detail']
    except (ValueError, TypeError, KeyError):
        return False
    return isinstance(detail, list) and bool(detail) and all(
        isinstance(item, dict) and isinstance(item.get('loc'), list) and
        item['loc'] and item['loc'][0] == 'body' and item.get('type') in
        {'value_error', 'missing', 'string_type', 'string_too_short', 'string_too_long', 'extra_forbidden'}
        for item in detail)


class ComposioBrowserClient:
    def __init__(self, settings, api_key):
        self.settings = settings
        self.api_key = api_key

    def execute(self, slug, arguments):
        if slug not in TOOLS:
            raise AccessError('Only the configured Browser Use operations are available.', 403)
        payload = {
            'connected_account_id': self.settings['connected_account_id'],
            'user_id': self.settings['connection_user_id'],
